<script setup lang="ts">
import DeadlineEditor from '../components/DeadlineEditor.vue'
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {api,req,type CampaignRow} from '../api'
import {toast,state,currentAccount,updateQueue} from '../store'
import PrizeEditor from '../components/PrizeEditor.vue'
import BlockAuthor from '../components/BlockAuthor.vue'
import ReviewEntry from '../components/ReviewEntry.vue'
import Icon from '../components/Icon.vue'
import IconButton from '../components/IconButton.vue'
import DateField from '../components/DateField.vue'
import Modal from '../components/Modal.vue'
import {deadlineTone,deadlineHint} from '../deadline'
const tableScroller=ref<HTMLElement>(),clockNow=ref(Date.now())
const route=useRoute(),rows=ref<CampaignRow[]>([]),total=ref(0),page=ref(0),loading=ref(false),busy=ref(false)
const keyword=ref(''),kinds=ref<string[]>([]),statuses=ref<string[]>([]),timeField=ref('published'),after=ref(''),before=ref(''),order=ref('newest'),selected=ref<number[]>([]),filtersOpen=ref(false)
const manualReview=computed(()=>route.query.prizes==='unknown')
const reviewBusy=ref(false),prizeToolsOpen=ref(false)
const filterCount=computed(()=>kinds.value.length+statuses.value.length+Number(missingOnly.value)+Number(onlyOpen.value)+Number(!!after.value)+Number(!!before.value))
const section=computed(()=>manualReview.value?'prizes':route.path==='/shelf'?'shelved':route.path==='/cleaned'?'cleaned':'')
const KINDS:Record<string,string>={interactive:'互动',share:'转发',comment:'评论',reserve:'预约'}
const STATES:Record<string,string>={unjoined:'未参加',enrolled:'已参加',pending:'待开奖',won:'中奖',lost:'未中奖'}
const missingOnly=ref(false),onlyOpen=ref(false)
const prize=ref<{enabled:boolean;total:number;counts:Record<string,number>;attention:number;note:string}>()
const pages=computed(()=>Math.max(1,Math.ceil(total.value/40)))
const expired=(r:CampaignRow)=>r.draw_state==='ended'||!!(r.expires_at||r.deadline_at)&&Date.parse((r.expires_at||r.deadline_at)!)<=Date.now()
const eligible=(r:CampaignRow)=>!section.value&&!r.enrollment_id&&!r.queued&&!expired(r)&&!['unverified','unsupported'].includes(r.draw_state||'')
const all=computed({get:()=>rows.value.some(eligible)&&rows.value.filter(eligible).every(r=>selected.value.includes(r.id)),set:(v:boolean)=>selected.value=v?rows.value.filter(eligible).map(r=>r.id):[]})
let version=0,poll:ReturnType<typeof setInterval>|undefined
function iso(s:string){return s?new Date(s).toISOString():''}
async function load(){const v=++version;loading.value=true;try{const d=await api.campaigns({keyword:keyword.value,kind:kinds.value.join(','),statuses:statuses.value.join(','),state:section.value,time_field:timeField.value,after:iso(after.value),before:iso(before.value),order:order.value,prize_state:(manualReview.value||missingOnly.value)?'unknown':'',availability:onlyOpen.value?'open':'',limit:40,offset:page.value*40});if(v===version){rows.value=d.items;total.value=d.total;if(page.value>=pages.value){page.value=pages.value-1;void load();return;}selected.value=selected.value.filter(id=>d.items.some(r=>r.id===id&&eligible(r)))}}catch(e){toast(String(e),'danger')}finally{if(v===version)loading.value=false}}
function search(){page.value=0;void load();if(tableScroller.value)tableScroller.value.scrollTop=0}
async function turnPage(delta:number){page.value+=delta;await load();if(tableScroller.value)tableScroller.value.scrollTop=0}
function resetFilters(){missingOnly.value=manualReview.value;onlyOpen.value=false;keyword.value='';kinds.value=[];statuses.value=[];after.value='';before.value='';timeField.value='published';order.value='newest'}
function reset(){resetFilters();search()}
function when(s:string|null){if(!s)return '未提供';return new Date(s).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}
function conclusion(r:CampaignRow){if(r.draw_state==='ended')return '已开奖 / 截止';if(['unverified','unsupported'].includes(r.draw_state||''))return '待核对';return r.cleaned?'已清理':r.shelf_reason==='manual'&&!r.enrollment_id?'手动清理':!r.enrollment_id?(r.shelf_reason==='expired'||expired(r)?'日期截止':'未参加'):r.verdict==='won'?'中奖':r.verdict==='lost'?'未中奖':['blocked','failed','planned'].includes(r.enrollment_stage||'')?'参与未完成':'待开奖'}
async function dismiss(r:CampaignRow){const owner=currentAccount();busy.value=true;try{await api.dismiss(r.id,manualReview.value);updateQueue(await api.pool(),owner);await load();await progress();toast('已移到往期架','ok')}catch(e){toast(String(e),'danger')}finally{busy.value=false}}
async function add(ids:number[]){const owner=currentAccount();busy.value=true;try{const pool=await api.editPool({operation:'add',campaign_ids:ids});updateQueue(pool,owner);selected.value=[];await load();toast('已加入待参与','ok')}catch(e){toast(String(e),'danger')}finally{busy.value=false}}
async function shelf(r?:CampaignRow){busy.value=true;try{if(r)await api.restore(r.id);else{if(!confirm('将全部已截止活动收入往期架？'))return;await api.shelve()}await load()}catch(e){toast(String(e),'danger')}finally{busy.value=false}}
async function progress(){try{prize.value=await req('/api/campaigns/prizes')}catch{}}
async function review(){reviewBusy.value=true;try{prize.value=await req('/api/campaigns/prizes?enabled='+!prize.value?.enabled,{method:'POST'});toast(prize.value?.enabled?'自动核对已开启':'自动核对已暂停','ok')}catch(e){toast(String(e),'danger')}finally{reviewBusy.value=false}}
const account=state.overview?.accounts.find(r=>r.current)?.id??'anon'
let storageKey=`discovery:${account}:${route.fullPath}`
function remember(){sessionStorage.setItem(storageKey,JSON.stringify({keyword:keyword.value,kinds:kinds.value,statuses:statuses.value,timeField:timeField.value,after:after.value,before:before.value,order:order.value,page:page.value,missingOnly:missingOnly.value,onlyOpen:onlyOpen.value}))}
function restore(){try{const saved=JSON.parse(sessionStorage.getItem(storageKey)||'{}');for(const [key,target] of Object.entries({keyword,kinds,statuses,timeField,after,before,order,page,missingOnly,onlyOpen})){if(saved[key]!==undefined)target.value=saved[key]}}catch{}}
watch(()=>route.fullPath,()=>{remember();storageKey=`discovery:${account}:${route.fullPath}`;page.value=0;selected.value=[];filtersOpen.value=false;resetFilters();restore();void load()})
onMounted(()=>{resetFilters();restore();void load();void progress();poll=setInterval(()=>{clockNow.value=Date.now();void progress();if(!busy.value)void load()},30000)})
onUnmounted(()=>{remember();if(poll)clearInterval(poll)})
</script>
<template><div class="discovery-workspace">
<section class="panel discovery-filters"><div class="toolbar"><input class="ipt search" v-model="keyword" placeholder="活动奖品、UP 或动态号" @keyup.enter="search"/><button @click="search"><Icon name="search" :size="16"/>搜索</button><button :class="{primary:filterCount>0}" @click="filtersOpen=!filtersOpen"><Icon name="filter" :size="16"/>筛选<span v-if="filterCount"> · {{filterCount}}</span></button><select class="ipt sort" v-model="order" @change="search"><option value="newest">未参加优先 · 最新发布</option><option value="deadline">未参加优先 · 最早截止</option></select><button v-if="!section" class="primary" :disabled="busy||!selected.length" @click="add(selected)">加入待参与{{selected.length?' · '+selected.length:''}}</button><button v-if="!section" :disabled="busy" @click="shelf()"><Icon name="archive" :size="16"/>收存已截止</button><span class="muted total">{{total}} 条</span><button v-if="!section||manualReview" class="prize-tools-button" @click="prizeToolsOpen=true"><Icon name="gift" :size="16"/>奖品识别<span v-if="prize?.attention"> · {{prize.attention}}</span></button></div>
</section>
<Modal v-if="filtersOpen" title="筛选活动奖品" @close="filtersOpen=false"><div class="filter-grid">
<div class="filter-group"><h3>范围</h3><div class="compact-options"><label><input type="checkbox" v-model="missingOnly" :disabled="manualReview" @change="search"/>奖品待补全</label><label><input type="checkbox" v-model="onlyOpen" @change="search"/>仅未截止</label></div></div>
<div class="filter-group"><h3>参与类型</h3><div class="compact-options"><label v-for="(label,key) in KINDS" :key="key"><input type="checkbox" v-model="kinds" :value="key" @change="search"/>{{label}}</label></div></div>
<div class="filter-group"><h3>参与结果</h3><div class="compact-options"><label v-for="(label,key) in STATES" :key="key"><input type="checkbox" v-model="statuses" :value="key" @change="search"/>{{label}}</label></div></div>
<div class="filter-group"><h3>时间</h3><div class="time-filters"><select class="ipt" v-model="timeField" @change="search"><option value="published">发布时间</option><option value="deadline">截止时间</option></select><DateField v-model="after" time label="起始时间" @change="search"/><span>至</span><DateField v-model="before" time label="结束时间" @change="search"/></div></div>
</div><div class="modal-actions"><button @click="reset">重置</button><button class="primary" @click="filtersOpen=false">显示 {{total}} 条</button></div></Modal>
<Modal v-if="prizeToolsOpen" title="奖品识别" @close="prizeToolsOpen=false"><div class="prize-progress" role="status"><Icon name="gift" :size="18"/>

<span>{{prize?.enabled?(prize?.counts.pending?'自动识别中':'本轮识别结束'):'自动识别已暂停'}}</span><span class="muted">已识别 {{(prize?.counts.verified||0)+(prize?.counts.manual||0)}} · 待识别 {{prize?.counts.pending||0}}</span><RouterLink class="review-link" to="/campaigns?prizes=unknown" @click="prizeToolsOpen=false">手动补全 {{prize?.attention||0}} 条 ↗</RouterLink><button class="mini" :disabled="reviewBusy" @click="review">{{reviewBusy?'更新中…':prize?.enabled?'暂停自动识别':'开启自动识别'}}</button>
<span v-if="prize?.note" class="warning">{{prize.note.replace(/^RemoteError:\s*(\[[^\]]+\]\s*)?/, '')}}</span></div></Modal>
<div v-if="manualReview" class="review-heading"><strong>待补全活动奖品</strong><RouterLink to="/campaigns" class="review-link">返回发现列表</RouterLink></div>
<section class="panel campaign-panel"><div ref="tableScroller" class="table-scroll"><table class="dense campaign-table"><thead><tr><th v-if="!section" class="check-col"><input type="checkbox" v-model="all" :disabled="busy" aria-label="选择本页可参与活动奖品"/></th><th>活动奖品</th><th class="up-col">UP</th><th class="type-col">类型</th><th class="date-col">截止时间</th><th class="state-col">结论</th><th class="action-col">本地安排</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td v-if="!section"><input type="checkbox" v-model="selected" :value="r.id" :disabled="busy||!eligible(r)" :aria-label="'选择 '+(r.reward||'奖品待补全')"/></td><td class="prize-cell"><a :href="'https://t.bilibili.com/'+r.dyn_id" target="_blank" rel="noreferrer" :title="r.reward||'奖品待补全'">{{r.reward||'奖品待补全'}}</a><small>发布：{{when(r.published_at)}}<PrizeEditor :id="r.id" @saved="load();progress()"/></small></td><td class="author-cell"><div class="author-inline"><span class="author-name" :title="r.up_name">{{r.up_name||'—'}}</span><BlockAuthor :uid="r.up_uid" :name="r.up_name" @saved="load();progress()"/></div></td><td><span class="kind-badge" :class="'kind-'+r.kind">{{KINDS[r.kind]||r.kind}}</span></td><td class="date-cell"><div class="deadline-inline"><span class="deadline-mark" :class="deadlineTone(r.deadline_at,clockNow)" :title="deadlineHint(deadlineTone(r.deadline_at,clockNow))">{{r.deadline_at?when(r.deadline_at):'未提供'}}</span><DeadlineEditor :id="r.id" @saved="load"/></div></td><td :title="r.draw_reason"><span class="chip" :class="r.verdict==='won'?'chip-ok':''">{{conclusion(r)}}</span></td><td><div class="row-controls"><button v-if="section==='shelved'" :disabled="busy" @click="shelf(r)">取回</button><RouterLink v-else-if="r.queued" to="/pool" class="chip chip-ok">查看计划</RouterLink><button v-else-if="eligible(r)" :disabled="busy" @click="add([r.id])">加入</button><IconButton v-if="manualReview||!section&&!r.enrollment_id" icon="archive" :label="manualReview?'移出补全列表，收入往期架':'不参加，移到往期架'" :disabled="busy" @click="dismiss(r)"/><ReviewEntry v-if="r.enrollment_id" :dynamic="r.dyn_id" @saved="load"/><span v-if="r.kept" class="chip">保留</span></div></td></tr><tr v-if="!rows.length"><td :colspan="section?6:7" class="empty-state">{{loading?'读取中…':'没有匹配的活动奖品'}}</td></tr></tbody></table></div><footer class="pagination"><span>{{page+1}} / {{pages}}</span><button :disabled="!page||loading" @click="turnPage(-1)">上一页</button><button :disabled="page+1>=pages||loading" @click="turnPage(1)">下一页</button></footer></section>
</div></template>
<style scoped>
.uncertain-time{display:block;color:var(--muted);font-size:12px}

.review-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;font-size:var(--text-meta)}.prize-tools-button{font-size:var(--text-meta)}

.discovery-workspace{max-width:1440px;height:100%;min-height:420px;margin:auto;display:flex;flex-direction:column;gap:18px}.discovery-filters{flex:none;padding:20px;border-top:4px solid var(--discover)}.search{width:210px}.sort{width:205px}.total{margin-left:auto}.filter-grid{display:grid;gap:20px}.filter-group{display:grid;grid-template-columns:70px minmax(0,1fr);gap:12px;align-items:start}.filter-group h3{font-size:var(--text-meta);line-height:28px}.time-filters{display:grid;grid-template-columns:minmax(0,1fr) 20px minmax(0,1fr);gap:10px;align-items:center}.time-filters select{grid-column:1/-1;width:130px}.time-filters .date-field{min-width:0;width:100%}.prize-progress{flex:none;padding:12px 18px;border:1px solid var(--line);border-radius:var(--radius-panel);display:flex;align-items:center;flex-wrap:wrap;gap:14px;background:var(--surface);font-size:var(--text-meta)}.campaign-panel{display:flex;flex-direction:column;flex:1;min-height:0;overflow:hidden}.table-scroll{overflow:auto;flex:1;min-height:0}.campaign-table thead th{position:sticky;top:0;z-index:2;box-shadow:0 1px 0 var(--line)}.campaign-table{width:100%;min-width:1000px;table-layout:fixed}.campaign-table td,.campaign-table th{text-align:center;vertical-align:middle;white-space:normal}.campaign-table .prize-cell{text-align:left;min-width:260px}.prize-cell>a{text-decoration:none;font-weight:600;font-size:var(--text-body);color:var(--text);display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;line-height:1.7}.prize-cell small{display:block;margin-top:8px;color:var(--muted);font-size:12px}.prize-cell small a{color:var(--discover);margin-left:10px}.check-col{width:42px}.campaign-table th.check-col,.campaign-table td:has(>input[type=checkbox]){padding:10px 8px;text-overflow:clip;overflow:visible}.up-col{width:155px}.campaign-table .author-cell{min-width:160px;max-width:200px;padding-inline:14px}.author-name{display:block;min-width:0;max-width:150px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.6}.author-inline{display:flex;align-items:center;justify-content:center;gap:6px}.type-col{width:90px}.campaign-table td:has(>.kind-badge){min-width:90px;padding-inline:10px}.date-col{width:195px}.state-col{width:120px}.action-col{width:125px}.deadline-inline{display:flex;align-items:center;justify-content:center;gap:2px}.campaign-table .chip{max-width:none;white-space:nowrap}.campaign-table td{overflow:visible}.row-controls{flex-wrap:wrap}.date-cell{font-variant-numeric:tabular-nums;white-space:nowrap!important;font-size:var(--text-meta)}footer{flex:none;display:flex;justify-content:center;align-items:center;padding:18px;gap:14px;border-top:1px solid var(--line)}
.toolbar button{display:inline-flex;align-items:center;justify-content:center;gap:6px}
.review-link{color:var(--discover);font-weight:600;text-decoration:none}.review-link:hover{text-decoration:underline}.prize-progress .mini{margin-left:auto}
</style>
